 "[\"fraction-links\",0,\"Which fraction is equal to one half?\",\"Imagine two out of four equal pieces.\",\"2/4 and 1/2 name the same proportion.\",[\"2/4\",\"1/4\",\"3/4\"],null,null,null,null,null,null,null]",
 "[\"fraction-links\",0,\"Which fraction is equivalent to one half?\",\"The numerator must be half the denominator.\",\"3 is half of 6, so 3/6=1/2.\",[\"3/6\",\"2/6\",\"4/6\"],null,null,null,null,null,null,null]",
